message.content:
{
  "description": "The creature is a large upright chimeric animal shown in right-facing profile with both wings fully outstretched to the sides against a plain off-white background. It has the head and thick shaggy mane of a lion on top, a feathered upper chest and two broad feathered wings, and a spotted feline torso, hindquarters and long tail below. The lower body, hind legs and tail are covered in tan fur with dense dark brown rosette spots, while the neck, upper chest and wings are covered in overlapping brown, tan and cream feathers with darker tips and barring. It stands balanced on two muscular hind legs ending in large pawed feet, with no forelimbs visible, and its long tail curves down and then up to end in a dark bushy tuft. The overall coloration is warm golden-brown, tan and cream.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a lion's head in right profile with a tan muzzle, dark pinkish-brown nose, yellow eye with dark pupil, white chin and lower lip, visible whisker pores, and a closed mouth",
      "where": "at the top right of the body, above the maned neck"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears with dark inner fur and tan outer fur, one clearly visible in profile and the second partially visible behind it",
      "where": "on top of the head set within the mane"
    },
    {
      "part": "mane",
      "looks_like": "thick, shaggy, layered fur in golden-brown and tan with darker shading, forming a full ruff around the head and neck",
      "where": "encircling the head and extending down the back and sides of the neck to the feathered chest"
    },
    {
      "part": "legs",
      "looks_like": "two thick, muscular hind legs with bent joints, covered in tan fur with dark rosette spots",
      "where": "under the torso, supporting the upright stance; no forelimbs are visible"
    },
    {
      "part": "feet",
      "looks_like": "two large feline paws with rounded toe pads, short blunt claws and spotted fur on top",
      "where": "at the bottom ends of the two hind legs, planted on the ground"
    },
    {
      "part": "tail",
      "looks_like": "a long slender tail covered in tan fur with dark spots, curving downward from the rump then hooking upward, ending in a dark brown to black bushy tuft",
      "where": "extending from the rear of the hindquarters to the lower left"
    },
    {
      "part": "wings",
      "looks_like": "two large outstretched wings with broad layered flight feathers in shades of tan, light brown and dark brown with barred patterns and dark tips",
      "where": "attached at the upper back/shoulder on each side of the body, one extending to the left and one to the right"
    },
    {
      "part": "feathers",
      "looks_like": "dense overlapping feathers; small scale-like golden-brown feathers with darker centers on the neck and upper chest, and larger layered wing coverts and flight feathers with brown, tan and cream barring",
      "where": "covering both wings and the front of the neck and chest down to the mid-torso"
    },
    {
      "part": "markings",
      "looks_like": "dense dark brown to black rosette and solid spots of varying size on a tan background, leopard-like",
      "where": "covering the lower chest, belly, flanks, hind legs and tail"
    }
  ],
  "attached_objects": [],
  "animals": ["lion", "leopard", "eagle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
